// GENERATED by scripts/sync-functions.mjs from src/shared. Do not edit; run `npm run functions:sync`.
// Locale-aware formatting for numbers, money and dates.
//
// Intl does the locale work (grouping style, currency symbol placement). We
// always ask Intl for Latin digits and then transliterate ourselves, so digit
// output is identical on every JS engine (Hermes, V8, Deno) whatever ICU data
// it has. Each Intl call has a plain fallback for engines that lack it.

import { fromIso, type CalendarSystem } from './calendars.ts';
import { toDigitSystem, type DigitSystem } from './digits.ts';
import { splitMinor, usesToman, type MoneyDisplayOptions } from './money.ts';

export interface FormatLabels {
  /** Label shown after IRR amounts in toman mode, e.g. "toman" / "تومان". */
  toman: string;
  /** 12 month names per calendar, in the UI language. */
  months: Record<CalendarSystem, string[]>;
  /** Long date pattern using {day} {month} {year}, e.g. "{day} {month} {year}". */
  dateLong: string;
  /** Short numeric date pattern using {d} {m} {y}, e.g. "{d}/{m}/{y}". */
  dateShort: string;
}

export interface FormatContext extends MoneyDisplayOptions {
  locale: string;
  digits: DigitSystem;
  calendar: CalendarSystem;
  labels: FormatLabels;
}

const latnLocale = (locale: string) => `${locale}-u-nu-latn`;

interface NumberSymbols {
  group: (integer: string) => string;
  decimal: string;
}

const symbolsCache = new Map<string, NumberSymbols>();

function plainGroup(integer: string): string {
  return integer.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

function numberSymbols(locale: string): NumberSymbols {
  const cached = symbolsCache.get(locale);
  if (cached) return cached;
  let symbols: NumberSymbols = { group: plainGroup, decimal: '.' };
  try {
    const nf = new Intl.NumberFormat(latnLocale(locale), { maximumFractionDigits: 0 });
    const decimal =
      new Intl.NumberFormat(latnLocale(locale), { minimumFractionDigits: 1 })
        .formatToParts(1.5)
        .find((p) => p.type === 'decimal')?.value ?? '.';
    symbols = {
      // The integer part of a stored amount is always a safe integer.
      group: (integer) => nf.format(Number(integer)),
      decimal,
    };
  } catch {
    // keep fallback
  }
  symbolsCache.set(locale, symbols);
  return symbols;
}

/** Format a plain number (counts, percentages...). */
export function formatNumber(value: number, ctx: Pick<FormatContext, 'locale' | 'digits'>): string {
  let out: string;
  try {
    out = new Intl.NumberFormat(latnLocale(ctx.locale)).format(value);
  } catch {
    out = plainGroup(String(value));
  }
  return toDigitSystem(out, ctx.digits, true);
}

interface CurrencyAffix {
  prefix: string;
  suffix: string;
}

const affixCache = new Map<string, CurrencyAffix>();

function currencyAffix(locale: string, currency: string): CurrencyAffix {
  const key = `${locale}|${currency}`;
  const cached = affixCache.get(key);
  if (cached) return cached;
  let affix: CurrencyAffix = { prefix: '', suffix: ` ${currency}` };
  try {
    const parts = new Intl.NumberFormat(latnLocale(locale), {
      style: 'currency',
      currency,
      currencyDisplay: 'narrowSymbol',
    }).formatToParts(1);
    const first = parts.findIndex((p) => p.type === 'integer');
    const last = parts.length - 1 - [...parts].reverse().findIndex((p) => p.type === 'integer' || p.type === 'fraction');
    const isAffix = (p: Intl.NumberFormatPart) => p.type === 'currency' || p.type === 'literal';
    affix = {
      prefix: parts.slice(0, first).filter(isAffix).map((p) => p.value).join(''),
      suffix: parts.slice(last + 1).filter(isAffix).map((p) => p.value).join(''),
    };
    if (!affix.prefix && !affix.suffix) affix = { prefix: '', suffix: ` ${currency}` };
  } catch {
    // keep fallback
  }
  affixCache.set(key, affix);
  return affix;
}

/** Number part only ("1,250.5"), no currency. */
export function formatAmount(minor: number, currency: string, ctx: FormatContext): string {
  const { negative, integer, fraction } = splitMinor(minor, currency, ctx);
  const symbols = numberSymbols(ctx.locale);
  const text = `${negative ? '-' : ''}${symbols.group(integer)}${fraction ? symbols.decimal + fraction : ''}`;
  return toDigitSystem(text, ctx.digits, true);
}

/** Full money string with currency symbol or toman label, e.g. "$1,250.50", "۵۰۰٬۰۰۰ تومان". */
export function formatMoney(minor: number, currency: string, ctx: FormatContext): string {
  const amount = formatAmount(Math.abs(minor), currency, ctx);
  const sign = minor < 0 ? '-' : '';
  if (usesToman(currency, ctx)) return `${sign}${amount} ${ctx.labels.toman}`;
  const { prefix, suffix } = currencyAffix(ctx.locale, currency);
  return `${sign}${prefix}${amount}${suffix}`;
}

function fill(template: string, values: Record<string, string>): string {
  return template.replace(/\{(\w+)\}/g, (m, k: string) => values[k] ?? m);
}

/** Format an ISO calendar date ('YYYY-MM-DD') in the chosen calendar. */
export function formatDate(iso: string, ctx: FormatContext, style: 'long' | 'short' = 'long'): string {
  const d = fromIso(iso, ctx.calendar);
  const text =
    style === 'long'
      ? fill(ctx.labels.dateLong, {
          day: String(d.day),
          month: ctx.labels.months[ctx.calendar][d.month - 1] ?? String(d.month),
          year: String(d.year),
        })
      : fill(ctx.labels.dateShort, {
          d: String(d.day).padStart(2, '0'),
          m: String(d.month).padStart(2, '0'),
          y: String(d.year),
        });
  return toDigitSystem(text, ctx.digits);
}
